                    .setLastSequence(entry.lastSeq())
                    .setLastOffset(entry.lastDataOffset())
                    .setOffsetDelta(entry.lastOffsetDelta())
                    .setTimestamp(entry.lastTimestamp())
                    .setCoordinatorEpoch(entry.coordinatorEpoch())
